from collections.abc import Sequence

import sqlalchemy as sa
from alembic import op

# revision identifiers, used by Alembic.
revision: str = "ddbc9fbac99c"
down_revision: str | Sequence[str] | None = "4104eb21787a"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None


def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column(
        "posts",
        sa.Column(
            "like_count", sa.Integer(), server_default=sa.text("0"), nullable=False
        ),
    )
    op.execute("""
        CREATE FUNCTION increment_like_count() RETURNS trigger
        LANGUAGE plpgsql as $$
        BEGIN
            UPDATE posts
            SET like_count = like_count + 1
            WHERE id = NEW.post_id;
            RETURN NULL;
        END;
        $$;
    """)
    op.execute("""
            CREATE TRIGGER increment_like_count_after_liking_post AFTER INSERT ON post_likes
            FOR EACH ROW EXECUTE FUNCTION increment_like_count()
    """)
    op.execute("""
            CREATE FUNCTION decrement_like_count() RETURNS trigger
            LANGUAGE plpgsql as $$
            BEGIN
                UPDATE posts
                SET like_count = like_count - 1
                WHERE id = OLD.post_id;
                RETURN NULL;
            END;
            $$;
    """)
    op.execute("""
                CREATE TRIGGER decrement_like_count_after_unliking_post AFTER DELETE ON post_likes
                FOR EACH ROW EXECUTE FUNCTION decrement_like_count()
    """)
    # ### end Alembic commands ###


def downgrade() -> None:
    """Downgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.execute("DROP TRIGGER increment_like_count_after_liking_post ON post_likes")
    op.execute("DROP TRIGGER decrement_like_count_after_unliking_post ON post_likes")
    op.execute("DROP FUNCTION increment_like_count()")
    op.execute("DROP FUNCTION decrement_like_count()")
    op.drop_column("posts", "like_count")
    # ### end Alembic commands ###
